function fail(path, expected) {
  throw new TypeError(`${path} must be ${expected}`);
}

function resolveReference(root, reference) {
  const prefix = "#/$defs/";
  if (!reference.startsWith(prefix)) {
    throw new TypeError(`unsupported schema reference ${reference}`);
  }
  const resolved = root.$defs?.[reference.slice(prefix.length)];
  if (resolved === undefined) {
    throw new TypeError(`unknown schema reference ${reference}`);
  }
  return resolved;
}

function assertSchema(root, schema, value, path) {
  if (schema.$ref !== undefined) {
    assertSchema(root, resolveReference(root, schema.$ref), value, path);
    return;
  }
  if (schema.enum !== undefined) {
    if (!schema.enum.some((candidate) => Object.is(candidate, value))) {
      fail(path, `one of ${JSON.stringify(schema.enum)}`);
    }
    return;
  }
  if (schema.const !== undefined) {
    if (!Object.is(schema.const, value)) {
      fail(path, JSON.stringify(schema.const));
    }
    return;
  }
  if (schema.oneOf !== undefined) {
    const accepted = schema.oneOf.some((candidate) => {
      try {
        assertSchema(root, candidate, value, path);
        return true;
      } catch {
        return false;
      }
    });
    if (!accepted) {
      fail(path, "one recognized variant");
    }
    return;
  }
  if (schema.anyOf !== undefined) {
    const accepted = schema.anyOf.some((candidate) => {
      try {
        assertSchema(root, candidate, value, path);
        return true;
      } catch {
        return false;
      }
    });
    if (!accepted) {
      fail(path, "one recognized variant");
    }
    return;
  }
  if (Array.isArray(schema.type)) {
    if (value === null && schema.type.includes("null")) {
      return;
    }
    const concrete = schema.type.filter((candidate) => candidate !== "null");
    const accepted = concrete.some((candidate) => {
      try {
        assertSchema(root, { ...schema, type: candidate }, value, path);
        return true;
      } catch {
        return false;
      }
    });
    if (!accepted) {
      fail(path, concrete.join(" or "));
    }
    return;
  }
  if (schema.type === "object") {
    if (value === null || typeof value !== "object" || Array.isArray(value)) {
      fail(path, "an object");
    }
    const properties = schema.properties ?? {};
    for (const required of schema.required ?? []) {
      if (!Object.hasOwn(value, required)) {
        fail(`${path}.${required}`, "present");
      }
    }
    if (schema.additionalProperties === false) {
      for (const key of Object.keys(value)) {
        if (!Object.hasOwn(properties, key)) {
          fail(`${path}.${key}`, "absent");
        }
      }
    }
    for (const [key, property] of Object.entries(properties)) {
      if (Object.hasOwn(value, key)) {
        assertSchema(root, property, value[key], `${path}.${key}`);
      }
    }
    return;
  }
  if (schema.type === "array") {
    if (!Array.isArray(value)) {
      fail(path, "an array");
    }
    if (schema.maxItems !== undefined && value.length > schema.maxItems) {
      fail(path, `at most ${schema.maxItems} items`);
    }
    value.forEach((item, index) => assertSchema(root, schema.items, item, `${path}[${index}]`));
    return;
  }
  if (schema.type === "integer") {
    if (!Number.isSafeInteger(value)) {
      fail(path, "a safe integer");
    }
    if (schema.format === "uint32" && (value < 0 || value > 4294967295)) {
      fail(path, "an unsigned 32-bit integer");
    }
    if (schema.minimum !== undefined && value < schema.minimum) {
      fail(path, `at least ${schema.minimum}`);
    }
    if (schema.maximum !== undefined && value > schema.maximum) {
      fail(path, `at most ${schema.maximum}`);
    }
    return;
  }
  if (schema.type === "null") {
    if (value !== null) {
      fail(path, "null");
    }
    return;
  }
  if (typeof value !== schema.type) {
    fail(path, schema.type);
  }
  if (schema.type === "string" && schema.pattern !== undefined && !(new RegExp(schema.pattern)).test(value)) {
    fail(path, `a string matching ${schema.pattern}`);
  }
  if (
    schema.type === "string" &&
    (schema.pattern === "^[1-9][0-9]*$" || schema.pattern === "^(0|[1-9][0-9]*)$") &&
    BigInt(value) > 18446744073709551615n
  ) {
    fail(path, "an unsigned 64-bit integer");
  }
}

function sameTimelineAddress(left, right) {
  return left.event_sequence === right.event_sequence;
}

function sameBodyContinuation(left, right) {
  return (
    sameTimelineAddress(left.address, right.address) &&
    left.field === right.field &&
    left.member_index === right.member_index &&
    left.offset_bytes === right.offset_bytes
  );
}

function assertTimelineExcerpt(excerpt, address, field, memberIndex, path) {
  const offset = BigInt(excerpt.offset_bytes);
  const total = BigInt(excerpt.total_bytes);
  const end = offset + BigInt(new TextEncoder().encode(excerpt.text).byteLength);
  if (offset > total || end > total) {
    fail(path, "an excerpt within its declared byte range");
  }
  if (excerpt.continuation === undefined || excerpt.continuation === null) {
    if (end !== total) {
      fail(path, "complete when no continuation is present");
    }
    return null;
  }
  const continuation = excerpt.continuation;
  if (end >= total) {
    fail(`${path}.continuation`, "present only before the declared body end");
  }
  if (
    !sameTimelineAddress(continuation.address, address) ||
    continuation.field !== field ||
    continuation.member_index !== memberIndex
  ) {
    fail(`${path}.continuation`, "the same body member at the same address");
  }
  if (BigInt(continuation.offset_bytes) !== end) {
    fail(`${path}.continuation.offset_bytes`, "the byte immediately after the excerpt");
  }
  return continuation;
}

function pageToolContinuation(value, address, field) {
  if (
    value.continuation === undefined ||
    value.continuation === null ||
    value.continuation.type !== "more_body"
  ) {
    return null;
  }
  const continuation = value.continuation.body;
  if (
    !sameTimelineAddress(continuation.address, address) ||
    BigInt(continuation.offset_bytes) !== 0n
  ) {
    return null;
  }
  const allowed = field === "tool_arguments"
    ? new Set(["tool_arguments", "tool_result", "tool_failure", "goal_text"])
    : field === "tool_result" || field === "tool_failure"
      ? new Set(["tool_arguments", "goal_text"])
      : field === "goal_text"
        ? new Set(["goal_text"])
        : new Set();
  return allowed.has(continuation.field) ? continuation : null;
}

function assertTimelineDetailPage(value) {
  const maxProjectedBodyBytes = 65536;
  const detailEnvelopeBytes = 128;
  const terminalKinds = new Set([
    "turn_failed",
    "turn_completed",
    "turn_refused",
    "turn_cancelled",
    "turn_reconciliation_required",
  ]);
  const bodyOwnedKinds = new Set([
    "session_created",
    "session_model_settings_changed",
    "turn_model_settings_resolved",
    "input_accepted",
    "goal_turn_retired",
    "model_call_transition",
    "tool_batch_transition",
    "tool_approval_decided",
    "context_compacted",
    "turn_activated",
    "runner_state_transition",
    "delegation_update",
    "delegation_wake",
    ...terminalKinds,
  ]);
  let expectedBodyContinuation = null;
  let computedProjectedBodyBytes = 0;
  let previousAddress = null;
  value.items.forEach((item, index) => {
    const path = `timeline_detail_page.items[${index}]`;
    const address = BigInt(item.address.event_sequence);
    if (previousAddress !== null && address <= previousAddress) {
      fail(`${path}.address`, "strictly increasing after the previous item");
    }
    previousAddress = address;
    const excerpts = [];
    switch (item.body.type) {
      case "user_input":
        if (item.kind !== "input_accepted") {
          fail(`${path}.kind`, "input_accepted for a user_input body");
        }
        excerpts.push([item.body.text, "input_text", 0, `${path}.body.text`]);
        break;
      case "model_call":
        if (item.kind !== "model_call_transition") {
          fail(`${path}.kind`, "model_call_transition for a model_call body");
        }
        if (item.body.response !== undefined && item.body.response !== null) {
          excerpts.push([item.body.response, "model_response", 0, `${path}.body.response`]);
        }
        break;
      case "tool_batch":
        if (item.kind !== "tool_batch_transition") {
          fail(`${path}.kind`, "tool_batch_transition for a tool_batch body");
        }
        if (item.body.tools.length + item.body.goal_events.length > 1) {
          fail(`${path}.body`, "at most one projected tool or goal member");
        }
        item.body.tools.forEach((tool, memberIndex) => {
          const physical = tool.evidence.type === "physical_attempt" ? tool.evidence : null;
          if (physical !== null) {
            const terminalFailure = physical.state === "known_failed";
            if ((physical.cause !== undefined && physical.cause !== null) !== terminalFailure) {
              fail(
                `${path}.body.tools[${memberIndex}].evidence.cause`,
                "present exactly for a known_failed attempt",
              );
            }
            if (
              physical.result !== undefined &&
              physical.result !== null &&
              physical.state !== "completed"
            ) {
              fail(
                `${path}.body.tools[${memberIndex}].evidence.result`,
                "present only for a completed attempt",
              );
            }
            if (
              physical.failure !== undefined &&
              physical.failure !== null &&
              !terminalFailure
            ) {
              fail(
                `${path}.body.tools[${memberIndex}].evidence.failure`,
                "present only for a known_failed attempt",
              );
            }
            if (physical.state === "ambiguous" && physical.effect_posture !== "external_effect") {
              fail(
                `${path}.body.tools[${memberIndex}].evidence.effect_posture`,
                "external_effect for an ambiguous attempt",
              );
            }
          }
          const projectedTextFields = [tool.arguments, physical?.result, physical?.failure].filter(
            (excerpt) => excerpt !== undefined && excerpt !== null,
          );
          if (projectedTextFields.length > 1) {
            fail(`${path}.body.tools[${memberIndex}]`, "at most one projected text field");
          }
          if (tool.arguments !== undefined && tool.arguments !== null) {
            excerpts.push([tool.arguments, "tool_arguments", memberIndex, `${path}.body.tools[${memberIndex}].arguments`]);
          }
          if (physical?.result !== undefined && physical.result !== null) {
            excerpts.push([physical.result, "tool_result", memberIndex, `${path}.body.tools[${memberIndex}].evidence.result`]);
          }
          if (physical?.failure !== undefined && physical.failure !== null) {
            excerpts.push([physical.failure, "tool_failure", memberIndex, `${path}.body.tools[${memberIndex}].evidence.failure`]);
          }
        });
        item.body.goal_events.forEach((event, memberIndex) => {
          if (event.text !== undefined && event.text !== null) {
            excerpts.push([event.text, "goal_text", memberIndex, `${path}.body.goal_events[${memberIndex}].text`]);
          }
        });
        break;
      case "tool_approval_decision":
        if (item.kind !== "tool_approval_decided") {
          fail(`${path}.kind`, "tool_approval_decided for a tool_approval_decision body");
        }
        if (item.body.rationale !== undefined && item.body.rationale !== null) {
          excerpts.push([item.body.rationale, "approval_rationale", 0, `${path}.body.rationale`]);
        }
        break;
      case "goal_event":
        if (item.kind !== "goal_turn_retired") {
          fail(`${path}.kind`, "goal_turn_retired for a goal_event body");
        }
        if (item.body.event.text !== undefined && item.body.event.text !== null) {
          excerpts.push([item.body.event.text, "goal_text", 0, `${path}.body.event.text`]);
        }
        break;
      case "context_compaction":
        if (item.kind !== "context_compacted") {
          fail(`${path}.kind`, "context_compacted for a context_compaction body");
        }
        excerpts.push([item.body.summary, "compaction_summary", 0, `${path}.body.summary`]);
        break;
      case "reconciliation":
        if (item.kind !== "turn_reconciliation_required") {
          fail(`${path}.kind`, "turn_reconciliation_required for a reconciliation body");
        }
        if (
          item.body.exhausted !== true ||
          item.body.operator_required !== true ||
          item.body.cause_code !== "ambiguous_operation"
        ) {
          fail(
            `${path}.body`,
            "an exhausted operator-required ambiguous_operation reconciliation",
          );
        }
        break;
      case "runner":
        if (item.kind !== "runner_state_transition") {
          fail(`${path}.kind`, "runner_state_transition for a runner body");
        }
        break;
      case "delegation": {
        const wake =
          item.body.detail.type === "result_wake" ||
          item.body.detail.type === "message_wake";
        if (wake && item.kind !== "delegation_wake") {
          fail(`${path}.kind`, "delegation_wake for a delegation wake body");
        }
        if (!wake && item.kind !== "delegation_update") {
          fail(`${path}.kind`, "delegation_update for a delegation update body");
        }
        const content =
          item.body.detail.type === "child_result"
            ? item.body.detail.content
            : item.body.detail.type === "session_message"
              ? item.body.detail.content
              : null;
        if (content !== undefined && content !== null) {
          excerpts.push([content, "delegation_content", 0, `${path}.body.detail.content`]);
        }
        break;
      }
      case "session_created":
        if (item.kind !== "session_created") {
          fail(`${path}.kind`, "session_created for a session_created body");
        }
        break;
      case "model_settings":
        if (
          item.body.detail.type === "session_defaults_changed" &&
          item.kind !== "session_model_settings_changed"
        ) {
          fail(
            `${path}.kind`,
            "session_model_settings_changed for session defaults detail",
          );
        }
        if (
          item.body.detail.type === "turn_resolved" &&
          item.kind !== "turn_model_settings_resolved"
        ) {
          fail(
            `${path}.kind`,
            "turn_model_settings_resolved for resolved turn detail",
          );
        }
        break;
      case "turn_lifecycle":
        if (item.body.lifecycle === "activated" && item.kind !== "turn_activated") {
          fail(`${path}.kind`, "turn_activated for an activated lifecycle");
        }
        if (item.body.lifecycle === "terminalized" && !terminalKinds.has(item.kind)) {
          fail(`${path}.kind`, "a terminal turn event for a terminalized lifecycle");
        }
        break;
      case "event_fact":
        if (item.body.kind !== item.kind || bodyOwnedKinds.has(item.kind)) {
          fail(`${path}.body.kind`, "the matching header-only event kind");
        }
        break;
    }
    let textBytes = 0;
    excerpts.forEach(([excerpt, field, memberIndex, excerptPath]) => {
      const continuation = assertTimelineExcerpt(
        excerpt,
        item.address,
        field,
        memberIndex,
        excerptPath,
      );
      textBytes += new TextEncoder().encode(excerpt.text).byteLength;
      if (continuation !== null) {
        if (expectedBodyContinuation !== null) {
          fail(path, "at most one continued body per page");
        }
        expectedBodyContinuation = continuation;
      }
    });
    const computedItemBytes = detailEnvelopeBytes + textBytes;
    if (item.projected_body_bytes !== computedItemBytes) {
      fail(`${path}.projected_body_bytes`, `the computed ${computedItemBytes} bytes`);
    }
    computedProjectedBodyBytes += computedItemBytes;
    if (computedProjectedBodyBytes > maxProjectedBodyBytes) {
      fail("timeline_detail_page.projected_body_bytes", `at most ${maxProjectedBodyBytes} bytes`);
    }
  });
  if (value.projected_body_bytes !== computedProjectedBodyBytes) {
    fail(
      "timeline_detail_page.projected_body_bytes",
      `the computed ${computedProjectedBodyBytes} bytes`,
    );
  }

  if (value.continuation === undefined || value.continuation === null) {
    if (expectedBodyContinuation !== null) {
      fail("timeline_detail_page.continuation", "the excerpt body continuation");
    }
    return;
  }
  if (value.continuation.type === "more_body") {
    if (
      expectedBodyContinuation !== null &&
      !sameBodyContinuation(value.continuation.body, expectedBodyContinuation)
    ) {
      fail("timeline_detail_page.continuation.body", "the excerpt body continuation");
    }
  } else {
    if (expectedBodyContinuation !== null) {
      fail("timeline_detail_page.continuation", "more_body for a continued excerpt");
    }
    if (
      previousAddress !== null &&
      BigInt(value.continuation.address.event_sequence) <= previousAddress
    ) {
      fail("timeline_detail_page.continuation.address", "after the final returned item");
    }
  }
}

export function decodeWebContractBootstrap(value) {
  assertSchema(schemas.WebContractBootstrap, schemas.WebContractBootstrap, value, "bootstrap");
  if (value.contract.name !== "signalbox.web-http" || value.contract.version !== "1") {
    throw new TypeError("bootstrap carries an incompatible web contract");
  }
  return value;
}

export function decodeWebContractExample(value) {
  assertSchema(schemas.WebContractExample, schemas.WebContractExample, value, "example");
  return value;
}

export function decodeWebApiErrorResponse(value) {
  assertSchema(schemas.WebApiErrorResponse, schemas.WebApiErrorResponse, value, "error_response");
  return value;
}

export function decodeWebSessionTimelineDescriptor(value) {
  assertSchema(schemas.WebSessionTimelineDescriptor, schemas.WebSessionTimelineDescriptor, value, "session_descriptor");
  return value;
}

export function decodeWebSessionTimelineWindow(value) {
  assertSchema(schemas.WebSessionTimelineWindow, schemas.WebSessionTimelineWindow, value, "timeline_window");
  return value;
}

export function decodeWebSessionTimelineDetailPage(value) {
  assertSchema(schemas.WebSessionTimelineDetailPage, schemas.WebSessionTimelineDetailPage, value, "timeline_detail_page");
  assertTimelineDetailPage(value);
  return value;
}
